import{c as a,Q as t,j as i,m as e}from"./chunks/framework.BXc4yaFE.js";const c=JSON.parse('{"title":"自訂 Claude Code 行為的七種機制","description":"","frontmatter":{},"headers":[],"relativePath":"research/best-practices/38-steering-claude-code.md","filePath":"research/best-practices/38-steering-claude-code.md","lastUpdated":1785909234000}'),l={name:"research/best-practices/38-steering-claude-code.md"};function n(o,s,r,d,h,p){return t(),i("div",null,[...s[0]||(s[0]=[e(`<h1 id="自訂-claude-code-行為的七種機制" tabindex="-1">自訂 Claude Code 行為的七種機制 <a class="header-anchor" href="#自訂-claude-code-行為的七種機制" aria-label="Permalink to &quot;自訂 Claude Code 行為的七種機制&quot;">​</a></h1><blockquote><p><strong>Source:</strong> <a href="https://claude.com/blog/steering-claude-code-skills-hooks-rules-subagents-and-more" target="_blank" rel="noreferrer">https://claude.com/blog/steering-claude-code-skills-hooks-rules-subagents-and-more</a><br><strong>Date:</strong> 2026-06-18<br><strong>Type:</strong> 官方指南 — 七種機制選擇指南</p></blockquote><hr><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>官方整理七種自訂 Claude Code 行為的機制，並提供清晰的選擇決策框架。核心問題：</p><ul><li>要改變 <strong>Claude 知道什麼</strong>（Know）→ CLAUDE.md / Rules / Skills</li><li>要改變 <strong>Claude 呼叫什麼工具</strong>（What Tools）→ Subagents / MCP</li><li>要在 <strong>生命週期事件自動執行</strong>（Automate）→ Hooks</li><li>要改變 <strong>Claude 回應的外觀</strong>（Output Appearance）→ Output Styles / System Prompt Appending</li></ul><hr><h2 id="七種機制" tabindex="-1">七種機制 <a class="header-anchor" href="#七種機制" aria-label="Permalink to &quot;七種機制&quot;">​</a></h2><h3 id="_1-claude-md" tabindex="-1">1. CLAUDE.md <a class="header-anchor" href="#_1-claude-md" aria-label="Permalink to &quot;1. CLAUDE.md&quot;">​</a></h3><p><strong>用途</strong>：提供持久 context，告訴 Claude 你的工作環境和偏好。</p><ul><li>存放位置：workspace 根目錄 <code>CLAUDE.md</code>（影響整個 workspace），或子目錄（影響子目錄）</li><li>適合：tech stack、常見命令、Code style、專案特定慣例、重要目錄</li><li><strong>長度 ≤ 200 行（最佳 60 行）</strong>，只寫會改變 Claude 行為的內容</li><li>Claude 在 session 開始時自動載入</li><li>大型規則用 <code>.claude/rules/*.md</code> + <code>@import</code> 拆分</li></ul><h3 id="_2-rules-path-scoped-rules" tabindex="-1">2. Rules（Path-scoped Rules） <a class="header-anchor" href="#_2-rules-path-scoped-rules" aria-label="Permalink to &quot;2. Rules（Path-scoped Rules）&quot;">​</a></h3><p><strong>用途</strong>：針對特定路徑的條件式指令，避免不相關 token 消耗。</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">---</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">paths</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;**/*.py&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;src/api/**&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">---</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># Python 特定規則</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">使用 Pydantic V2 型別標注...</span></span></code></pre></div><ul><li>只在存取相關檔案時載入，降低 token 消耗</li><li>適合：語言特定規範、目錄特定流程、安全敏感區域的額外限制</li><li>比 CLAUDE.md 主體更符合「按需載入」原則</li></ul><h3 id="_3-skills" tabindex="-1">3. Skills <a class="header-anchor" href="#_3-skills" aria-label="Permalink to &quot;3. Skills&quot;">​</a></h3><p><strong>用途</strong>：打包可重用的知識、工作流和最佳實踐。</p><ul><li>存放位置：<code>.claude/skills/&lt;name&gt;/</code>（資料夾形式，非只是 markdown）</li><li><strong>初始只載入名稱與描述</strong>，呼叫時才展開全文（降低 context 成本）</li><li>支援 nested 子目錄：<code>.claude/skills/backend/postgres/</code>（v2.1.178+）</li><li>名稱衝突以 <code>&lt;dir&gt;:&lt;name&gt;</code> 表示</li></ul><p><strong>Skill 的最佳 description 格式</strong>：</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">---</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">description</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">當需要...時使用。Do NOT use for</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">...</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">---</span></span></code></pre></div><p><strong>九大 Skill 類別</strong>（Anthropic 內部分類）：</p><ol><li>Library/API Reference（程式庫參考）</li><li>Product Verification（產品驗證）</li><li>Data Fetching（資料抓取）</li><li>Business Process（業務流程）</li><li>Code Scaffolding（代碼鷹架）</li><li>Code Quality（代碼品質）</li><li>CI/CD（持續整合部署）</li><li>Runbooks（操作手冊）</li><li>Infrastructure Ops（基礎架構操作）</li></ol><h3 id="_4-subagents" tabindex="-1">4. Subagents <a class="header-anchor" href="#_4-subagents" aria-label="Permalink to &quot;4. Subagents&quot;">​</a></h3><p><strong>用途</strong>：將任務委派給獨立 context window 的 Claude 實例，並行或隔離執行。</p><ul><li>適合：research 密集任務、需要並行的任務、需要隔離 context 的驗證任務</li><li><strong>委派門檻</strong>：預期工具呼叫 &gt; 20 次，或讀取 ≥ 10 個檔案</li><li>v2.1.178 起：Agent Teams 簡化，直接用 <code>Agent</code> tool 的 <code>name</code> 參數 spawn 隊友，無需 <code>TeamCreate</code>/<code>TeamDelete</code></li></ul><h3 id="_5-hooks" tabindex="-1">5. Hooks <a class="header-anchor" href="#_5-hooks" aria-label="Permalink to &quot;5. Hooks&quot;">​</a></h3><p><strong>用途</strong>：生命週期事件的確定性觸發器（非 Claude 建議，是硬執行）。</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;hooks&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;PostToolUse&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;matcher&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Write&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;hooks&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;command&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;command&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;prettier --write $FILE_PATH&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><ul><li><strong>事件類型</strong>：PreToolUse / PostToolUse / Notification / Stop / PreCompact</li><li><strong>Exit code</strong>：0=成功、1=警告繼續、2=阻斷</li><li>適合：自動格式化、linter、Slack 通知、封鎖危險操作、test runner</li><li>v2.1.178+：<code>Tool(param:value)</code> 語法支援工具輸入參數比對</li></ul><h3 id="_6-output-styles" tabindex="-1">6. Output Styles <a class="header-anchor" href="#_6-output-styles" aria-label="Permalink to &quot;6. Output Styles&quot;">​</a></h3><p><strong>用途</strong>：改變 Claude 回應格式而無需修改 Prompt。</p><ul><li>在 CLAUDE.md 中定義：<code>偏好列點清單而非散文回應</code></li><li>適合：統一團隊輸出格式、特定輸出格式需求（JSON / XML / etc.）</li></ul><h3 id="_7-system-prompt-appending" tabindex="-1">7. System Prompt Appending <a class="header-anchor" href="#_7-system-prompt-appending" aria-label="Permalink to &quot;7. System Prompt Appending&quot;">​</a></h3><p><strong>用途</strong>：透過 API 或 Claude Code SDK 在系統 prompt 末尾追加指令。</p><ul><li>適合：動態注入 context（如當前日期/用戶資訊）、多租戶系統</li><li><code>&lt;system-reminder&gt;</code> 標籤：在訊息流中注入動態更新，保護 system prompt 快取前綴不失效</li></ul><hr><h2 id="選擇指南" tabindex="-1">選擇指南 <a class="header-anchor" href="#選擇指南" aria-label="Permalink to &quot;選擇指南&quot;">​</a></h2><table tabindex="0"><thead><tr><th>需求</th><th>使用機制</th></tr></thead><tbody><tr><td>改變 Claude 知道的事情（持久）</td><td>CLAUDE.md</td></tr><tr><td>路徑特定規則（按需）</td><td>Path-scoped Rules</td></tr><tr><td>可重用工作流或知識</td><td>Skills</td></tr><tr><td>並行任務 / 隔離 context</td><td>Subagents</td></tr><tr><td>生命週期自動化（硬執行）</td><td>Hooks</td></tr><tr><td>輸出格式設定</td><td>Output Styles</td></tr><tr><td>動態 context 注入</td><td>System Prompt Appending</td></tr></tbody></table><hr><h2 id="關鍵原則" tabindex="-1">關鍵原則 <a class="header-anchor" href="#關鍵原則" aria-label="Permalink to &quot;關鍵原則&quot;">​</a></h2><ol><li><strong>機制組合使用</strong>：CLAUDE.md + Rules + Skills + Hooks 是大型 Codebase 的完整 Harness</li><li><strong>惰性載入</strong>：Skills 和 Path-scoped Rules 只在需要時載入，優先選擇這些機制降低 token 消耗</li><li><strong>Hooks 是確定性的</strong>：Hooks 不受 prompt 影響，比在 CLAUDE.md 中說「請記得格式化」更可靠</li><li><strong>每 3-6 個月審閱</strong>：模型更新後，舊指令可能反而限制新模型能力</li><li><strong>CLAUDE.md 精簡</strong>：只放「會改變 Claude 行為的內容」，可從 repo 推導的資訊 = 噪音</li></ol><hr><h2 id="延伸閱讀" tabindex="-1">延伸閱讀 <a class="header-anchor" href="#延伸閱讀" aria-label="Permalink to &quot;延伸閱讀&quot;">​</a></h2><ul><li><a href="./01-official-hooks-memory-settings">01-official-hooks-memory-settings.md</a> — Hook 詳細架構</li><li><a href="./06-agent-skills-best-practices">06-agent-skills-best-practices.md</a> — Skill 撰寫原則</li><li><a href="./21-memory-claudemd">21-memory-claudemd.md</a> — CLAUDE.md 多層級設定</li><li><a href="./33-skills-nine-categories">33-skills-nine-categories.md</a> — Skill 九大類別詳解</li></ul>`,44)])])}const u=a(l,[["render",n]]);export{c as __pageData,u as default};
